    [269828] = { k = "ritual", zone = "zulaman", how = "In the Broken Throne ritual site (tier 2 or higher), complete the ritual circle and kill the eagle it summons.", steps = { { map = 2585, x = 51.5, y = 47.8, text = "Enter the Broken Throne ritual site on tier 2 or higher and take the Misplaced Ritual Candle from the tree here" }, { map = 2585, x = 50.75, y = 47.16, text = "Place it on the empty spot at the north-east of the Ritual Circle" }, { map = 2585, x = 50.6, y = 47.3, text = "Light the candle in the middle of the circle: the Void-Corrupted Hex Eagle appears. Kill it and loot the mount" } }, tips = { "If three Void-Corrupted Hex Eaglets appear instead, the missing candle wasn't placed first.", "Riding this mount inside the ritual site also leads to the pet Void-Scarred Eaglet." } },
    [269829] = { k = "ritual", zone = "zulaman", how = "Ride the Void-Corrupted Hex Eagle mount inside the Broken Throne ritual site: only then can you see the small tornado at the edge of the top platform. It lifts you to a nest that holds the pet.", steps = { { text = "Get the Void-Corrupted Hex Eagle mount first (Void-Corrupted Eagle Talon)", own = 269828 }, { map = 2585, x = 49.6, y = 77.9, text = "Mounted on the eagle, fly into the small tornado here and loot the nest" } }, tips = { "Glowing feathers on the ground lead the way." } },
    [269836] = { k = "ritual", zone = "zulaman", how = "In the Broken Throne ritual site (tier 2 or higher), find the Lost Bear Cub stealthed behind a tree and feed it 1 Practically Pork.", at = { { 2585, 55.81, 49.52 } }, tips = { "Bring 6 Practically Pork and you can also earn the Witherbark Warbear Harness mount in the same run." } },
    [269999] = { k = "ritual", zone = "eversong", needFac = 2792, needLvl = 8, how = "Can drop from the Mana-Gorged Greatwyrm, a rare on the water in the Daggerspine Point ritual site. It shows up from Ritual Sites Renown 8.", tips = { "Tier 1 works: kill it, loot it and leave; you don't need to finish the run.", "Water walking for your mount helps you reach it." } },
    [270041] = { k = "ritual", zone = "eversong", how = "In the Daggerspine Point ritual site, click the Washed Up Kelp (one or two lie on the shores each run). Each can release enemies, and sometimes the Void-Touched Snapdragon: kill it for the mount.", at = { { 2594, 46, 45 }, { 2594, 61, 77 }, { 2594, 47, 72 }, { 2594, 66, 74 }, { 2594, 41, 73 }, { 2594, 38, 64 }, { 2594, 53, 55 } }, tips = { "Any tier works, tier 1 included.", "Starry-Eyed Goggles make the kelp easier to spot." } },
